mapper.sql:
WHERE m.apply_status = 'APPROVED'
  AND m.status = 'OPEN'
  AND s.status = 'OPEN'
  AND c.status = 'OPEN'
  AND d.status != 'DELETED'

    AND d.canteen_id = #{query.canteenId}


    AND d.stall_id = #{query.stallId}


    AND d.merchant_id = #{query.merchantId}


    AND d.category_id = #{query.categoryId}


    AND EXISTS (
        SELECT 1
        FROM dish_tag dt
        WHERE dt.dish_id = d.id
          AND dt.tag_id = #{query.tagId}
    )


    AND d.price >= #{query.minPrice}


    AND d.price <= #{query.maxPrice}


    AND d.average_score >= #{query.minScore}


    AND d.name LIKE CONCAT('%', #{query.keyword}, '%')





                AND d.status = #{query.status}


                AND d.status = #{query.status}


                AND 1 = 0





            AND d.status IN ('ON_SALE', 'SOLD_OUT')

mapper.select:
SELECT d.id, d.merchant_id AS merchantId, d.canteen_id AS canteenId, d.stall_id AS stallId, d.name, d.description, d.price, d.category_id AS categoryId, cg.name AS categoryName, d.average_score AS score, d.status, d.is_join_lottery AS isJoinLottery, d.view_count AS viewCount, d.favorite_count AS favoriteCount, d.review_count AS commentCount, c.name AS canteenName, c.type AS canteenType, s.name AS stallName, m.name AS merchantName, d.taste_score AS tasteScore, d.portion_score AS portionScore, d.value_score AS valueScore FROM dish d INNER JOIN merchant m ON m.id = d.merchant_id INNER JOIN stall s ON s.id = d.stall_id INNER JOIN canteen c ON c.id = d.canteen_id LEFT JOIN category cg ON cg.id = d.category_id WHERE d.id = #{id} AND m.apply_status = 'APPROVED' AND m.status = 'OPEN' AND s.status = 'OPEN' AND c.status = 'OPEN' AND d.status IN
#{status}
LIMIT 1

SELECT d.id, d.merchant_id AS merchantId, d.canteen_id AS canteenId, d.stall_id AS stallId, d.name, d.description, d.price, d.category_id AS categoryId, cg.name AS categoryName, d.average_score AS score, d.status, d.is_join_lottery AS isJoinLottery, d.view_count AS viewCount, d.favorite_count AS favoriteCount, d.review_count AS commentCount, c.name AS canteenName, c.type AS canteenType, s.name AS stallName, m.name AS merchantName, d.taste_score AS tasteScore, d.portion_score AS portionScore, d.value_score AS valueScore FROM dish d INNER JOIN merchant m ON m.id = d.merchant_id INNER JOIN stall s ON s.id = d.stall_id INNER JOIN canteen c ON c.id = d.canteen_id LEFT JOIN category cg ON cg.id = d.category_id WHERE d.id = #{id}
AND d.merchant_id = #{merchantId}
LIMIT 1

SELECT dt.dish_id AS dishId, t.id AS tagId, t.name AS tagName FROM dish_tag dt INNER JOIN tag t ON t.id = dt.tag_id WHERE dt.dish_id IN
#{dishId}
AND t.status = 'ACTIVE' ORDER BY t.sort_order ASC, t.id ASC

SELECT di.dish_id AS dishId, di.image_url AS imageUrl FROM dish_image di WHERE di.dish_id IN
#{dishId}
ORDER BY di.is_cover DESC, di.sort_order ASC, di.id ASC

mapper.update:
UPDATE dish
SET view_count = view_count + 1
WHERE id = #{id}
